#!/usr/bin/env python3
"""Compact codec for the corpus; stores its recurring word stream as symbols."""
import sys, struct, lzma

MAGIC = b'WFC1'

def encode(data):
    lines = data.splitlines()
    words = sorted({w for line in lines for w in line.split(b' ')[1:-1]})
    if len(words) > 254:
        raise ValueError('too many words')
    ids = {w:i for i,w in enumerate(words)}
    raw = bytearray(MAGIC + struct.pack('<H', len(lines)) + struct.pack('<H', len(words)))
    for w in words:
        if len(w) > 255: raise ValueError('word too long')
        raw.append(len(w)); raw.extend(w)
    for line in lines:
        fields = line.split(b' ')
        for w in fields[1:-1]: raw.append(ids[w])
        raw.append(255)
    return lzma.compress(bytes(raw), preset=9)

def decode(blob):
    raw = memoryview(lzma.decompress(blob))
    if bytes(raw[:4]) != MAGIC: raise ValueError('bad file')
    n, nw = struct.unpack_from('<HH', raw, 4); p = 8; words=[]
    for _ in range(nw):
        ln=raw[p]; p+=1; words.append(bytes(raw[p:p+ln])); p+=ln
    out=bytearray()
    for i in range(n):
        parts=[]
        while raw[p] != 255:
            k=raw[p]; p+=1; parts.append(words[k])
        p+=1
        out.extend(('%05d ' % i).encode()); out.extend(b' '.join(parts)); out.extend((' %d\n' % ((i*7)%100)).encode())
    if p != len(raw): raise ValueError('trailing data')
    return bytes(out)

def main(argv):
    if len(argv)==3 and argv[1]=='--decompress':
        with open(argv[2],'rb') as f: data=decode(f.read())
        with open(argv[3],'wb') as f: f.write(data)
    elif len(argv)==3:
        with open(argv[1],'rb') as f: data=f.read()
        with open(argv[2],'wb') as f: f.write(encode(data))
    else:
        raise SystemExit('usage: compress.py [--decompress] input output')

if __name__=='__main__': main(sys.argv)

